function slugify(value){return value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,120)||'produto'}
async function findCategory(slug,token){const q=new URLSearchParams({select:'id,name,slug',slug:`eq.${slug}`,active:'eq.true',limit:'1'});const rows=await adminRest(`categories?${q}`,{token});if(!rows[0])throw new Error('A categoria selecionada não está ativa no Supabase.');return rows[0]}
