function orderDestination(o){
 const address=o.shippingAddress||{},hasAddress=Boolean(address.street&&address.number&&address.district&&address.city&&address.state&&address.postal_code);
 if(!hasAddress){const cep=o.shippingDestination?` CEP da cotação: ${escapeHTML(o.shippingDestination)}.`:'';return `<span class="destination-missing">${o.environment==='teste'?'Endereço completo não registrado neste pedido de teste antigo.':'Endereço de entrega indisponível.'}${cep}</span>`}
 const location=[address.city,address.state].filter(Boolean).map(escapeHTML).join(' / '),complement=address.complement?` · ${escapeHTML(address.complement)}`:'';
 const phone=String(o.customerPhone||'').trim();
 return `<address class="order-destination"><strong>${escapeHTML(o.customer||'Destinatário')}</strong><span>${escapeHTML(address.street)}, ${escapeHTML(address.number)}${complement}</span><span>${escapeHTML(address.district)} · ${location}</span><span>CEP ${escapeHTML(address.postal_code)}</span>${phone?`<a href="tel:${escapeHTML(phone.replace(/[^0-9+]/g,''))}">Telefone: ${escapeHTML(phone)}</a>`:''}${o.shippingService?`<span class="destination-service">${escapeHTML(o.shippingService)}${Number.isFinite(o.shippingPrice)?` · ${money(o.shippingPrice)}`:''}${o.deliveryDays?` · ${escapeHTML(o.deliveryDays)} dias úteis`:''}</span>`:''}</address>`
}
function fulfillmentLabel(status){return ({pending:'Aguardando envio',quoted:'Frete definido',label_created:'Etiqueta criada',shipped:'Enviado',delivered:'Entregue',cancelled:'Cancelado'})[status]||'Aguardando envio'}
function orderItemMarkup(item){const options=Object.entries(item.options&&typeof item.options==='object'?item.options:{}).map(([key,value])=>`${escapeHTML(key)}: ${escapeHTML(value)}`).join(' · ');const meta=[item.sku?`SKU ${escapeHTML(item.sku)}`:'',options,`${item.quantity} × ${money(item.unitPriceCents/100)}`].filter(Boolean).join(' · ');return `<li class="order-line-item"><div><strong>${escapeHTML(item.name||'Produto')}</strong><small>${meta}</small></div><b>${money(item.lineTotalCents/100)}</b></li>`}
function orderProductsMarkup(order,expanded=false){const items=Array.isArray(order.lineItems)?order.lineItems:[];if(!items.length)return '<span class="destination-missing">Itens não disponíveis neste registro antigo.</span>';const lines=items.map(orderItemMarkup).join(''),summary=`${items.length} ${items.length===1?'produto':'produtos'} · ${order.itemCount} ${order.itemCount===1?'unidade':'unidades'}`;return expanded||items.length===1?`<ul class="order-items-list">${lines}</ul>`:`<details class="order-items-detail"><summary>${summary} · Ver detalhes</summary><ul class="order-items-list">${lines}</ul></details>`}
function orderTable(list,{allowSync=false,allowManage=false,expandedProducts=false}={}){
 if(!list.length)return '<p class="admin-empty">Nenhum pedido encontrado para este filtro.</p>';
 const syncAction=o=>allowSync&&o.environment==='teste'&&o.paymentStatus==='pending'&&o.paymentReference?`<button class="button button-outline" type="button" data-sync-sandbox="${escapeHTML(o.paymentReference)}">Atualizar pagamento no MP</button>`:'';
 const manageAction=o=>allowManage&&o.paymentStatus==='approved'?`<button class="button button-outline" type="button" data-manage-fulfillment="${escapeHTML(o.dbId)}" data-environment="${escapeHTML(o.environment)}">Gerenciar envio</button>`:'';
 const actions=o=>[syncAction(o),manageAction(o)].filter(Boolean).join('');
 const paymentBadge=o=>`<span class="status-label ${o.paymentStatus==='approved'?'':'pending'}">${escapeHTML(o.status)}</span>`;
 const shippingBadge=o=>`<span class="status-label fulfillment-status ${['shipped','delivered'].includes(o.shippingStatus)?'fulfilled':''}">${escapeHTML(fulfillmentLabel(o.shippingStatus))}</span>${o.trackingCode?`<small class="tracking-preview">Rastreio: ${escapeHTML(o.trackingCode)}</small>`:''}`;
 const rows=list.map(o=>`<tr><td class="order-id-cell">${escapeHTML(o.id)}<small>${escapeHTML(o.date)}</small></td><td>${escapeHTML(o.customer)}${o.customerEmail?`<small>${escapeHTML(o.customerEmail)}</small>`:''}</td><td class="order-products-cell">${orderProductsMarkup(o,expandedProducts)}</td><td>${money(o.total)}</td><td>${paymentBadge(o)}</td><td>${shippingBadge(o)}</td><td><span class="status-label ${o.environment==='teste'?'pending':''}">${o.environment==='teste'?'Teste':'Produção'}</span></td><td class="order-destination-cell">${orderDestination(o)}</td>${allowSync||allowManage?`<td class="order-actions-cell">${actions(o)}</td>`:''}</tr>`).join('');
 const cards=list.map(o=>`<article class="mobile-data-card order-mobile-card"><div class="mobile-data-card-head"><h3>${escapeHTML(o.id)}</h3>${paymentBadge(o)}</div><div class="order-status-row"><span class="eyebrow">Expedição</span>${shippingBadge(o)}</div><dl><div><dt>Cliente</dt><dd>${escapeHTML(o.customer)}</dd></div><div><dt>Produtos</dt><dd>${o.lineItems.length} ${o.lineItems.length===1?'produto':'produtos'} · ${o.itemCount} un.</dd></div><div><dt>Total</dt><dd>${money(o.total)}</dd></div><div><dt>Ambiente</dt><dd>${o.environment==='teste'?'Teste':'Produção'}</dd></div><div><dt>Pedido em</dt><dd>${escapeHTML(o.date)}</dd></div></dl><section class="order-products-mobile"><h4>Produtos do pedido</h4>${orderProductsMarkup(o,true)}</section><section class="order-shipping-destination"><h4>Enviar para</h4>${orderDestination(o)}</section>${actions(o)}</article>`).join('');
 return `<div class="desktop-data-view table-wrap"><table class="admin-table admin-table-orders"><thead><tr><th>Pedido</th><th>Cliente</th><th>Produtos</th><th>Total</th><th>Pagamento</th><th>Expedição</th><th>Ambiente</th><th>Destino de envio</th>${allowSync||allowManage?'<th>Ações</th>':''}</tr></thead><tbody>${rows}</tbody></table></div><div class="mobile-data-view" aria-label="Pedidos">${cards}</div>`
}
async function loadAdminOrders(token){const query=new URLSearchParams({select:'id,order_number,customer_name,customer_email,customer_phone,shipping_address,shipping_service,shipping_cents,shipping_quote_snapshot,total_cents,payment_status,shipping_status,tracking_code,status,created_at,order_items(id,product_name_snapshot,sku_snapshot,option_snapshot,unit_price_cents,quantity,line_total_cents)',order:'created_at.desc',limit:'100'});const [productionRows,sandboxRows]=await Promise.all([adminRest(`orders?${query}`,{token}),adminRest('rpc/admin_list_store_sandbox_orders_with_fulfillment',{method:'POST',body:{},token})]);const production=productionRows.map(o=>{const lineItems=(o.order_items||[]).map(item=>({name:item.product_name_snapshot,sku:item.sku_snapshot,options:item.option_snapshot,quantity:Number(item.quantity||0),unitPriceCents:Number(item.unit_price_cents||0),lineTotalCents:Number(item.line_total_cents||0)}));return {id:`#${o.order_number}`,dbId:o.id,customer:o.customer_name,customerEmail:o.customer_email,customerPhone:o.customer_phone,shippingAddress:o.shipping_address||{},shippingService:o.shipping_service||o.shipping_quote_snapshot?.service_name,shippingPrice:Number(o.shipping_cents||0)/100,deliveryDays:o.shipping_quote_snapshot?.delivery_days,shippingDestination:o.shipping_address?.postal_code,itemCount:lineItems.reduce((n,item)=>n+item.quantity,0),lineItems,total:Number(o.total_cents||0)/100,status:({pending:'Aguardando pagamento',approved:'Pago',rejected:'Recusado',cancelled:'Cancelado',refunded:'Reembolsado',expired:'Expirado'})[o.payment_status]||o.payment_status,paymentStatus:o.payment_status,shippingStatus:o.shipping_status,trackingCode:o.tracking_code||'',date:new Date(o.created_at).toLocaleDateString('pt-BR'),createdAt:o.created_at,environment:'produção'}});const testStatus={pending:'Aguardando pagamento (teste)',approved:'Pago (teste)',rejected:'Recusado (teste)',cancelled:'Cancelado (teste)',expired:'Expirado (teste)'};const sandbox=sandboxRows.map(o=>{const sourceItems=Array.isArray(o.items)?o.items:[],lineItems=sourceItems.map(item=>({name:item.name||item.product_name||'Produto',sku:item.sku||'',options:item.option_values||item.options||{},quantity:Number(item.quantity||0),unitPriceCents:Number(item.unit_price_cents||0),lineTotalCents:Number(item.line_total_cents||Number(item.unit_price_cents||0)*Number(item.quantity||0))}));return {id:`#${o.payment_reference||String(o.id).slice(0,8)}`,dbId:o.id,customer:o.customer?.name||'Comprador de teste',customerEmail:o.customer?.email||'',customerPhone:o.customer?.phone||'',shippingAddress:o.shipping_address||{},shippingService:o.shipping_quote?.service_name,shippingPrice:Number(o.shipping_quote?.price_cents??o.shipping_cents??0)/100,deliveryDays:o.shipping_quote?.delivery_days,shippingDestination:o.shipping_address?.postal_code||o.shipping_quote?.destination,itemCount:lineItems.reduce((n,item)=>n+item.quantity,0),lineItems,total:Number(o.total_cents||0)/100,status:testStatus[o.payment_status]||`${o.payment_status} (teste)`,date:new Date(o.created_at).toLocaleDateString('pt-BR'),createdAt:o.created_at,environment:'teste',paymentStatus:o.payment_status,paymentReference:o.payment_reference,shippingStatus:o.shipping_status||'quoted',trackingCode:o.tracking_code||''}});orders=[...production,...sandbox].sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));backendOrdersError='';ordersLoaded=true;return orders}
function stopOrdersAutoSync(){if(ordersAutoSyncTimer){clearInterval(ordersAutoSyncTimer);ordersAutoSyncTimer=null}activeOrdersList=null;activeOrdersFeedback=null}
async function syncSandboxPayment(reference,session){
 if(ordersSyncInFlight.has(reference))throw new Error('Este pedido já está sendo consultado.');
 ordersSyncInFlight.add(reference);
 try{
  const response=await fetch(`${supabaseConfig.supabaseUrl.replace(/\/$/,'')}/functions/v1/mercadopago-sync-sandbox-order`,{method:'POST',headers:{apikey:supabaseConfig.supabasePublishableKey,Authorization:`Bearer ${session.access_token}`,'Content-Type':'application/json'},body:JSON.stringify({payment_reference:reference})});
  let payload={};try{payload=await response.json()}catch{}
  if(!response.ok)throw new Error(payload.message||'A consulta automática ao Mercado Pago falhou. Tente novamente pelo botão.');
  return payload;
 }finally{ordersSyncInFlight.delete(reference)}
}
async function autoSyncSandboxOrders(list,feedback){
 if(ordersAutoSyncBusy||document.hidden||!list?.isConnected||activeOrdersList!==list)return;
 ordersAutoSyncBusy=true;
 try{
  const session=await getAuthSession();if(!session)throw new Error('Sessão expirada. Entre novamente no painel.');
  const pending=orders.filter(order=>order.environment==='teste'&&order.paymentStatus==='pending'&&order.paymentReference);
  const pendingRefs=new Set(pending.map(order=>order.paymentReference));
  for(const reference of ordersAutoSyncRetryAt.keys())if(!pendingRefs.has(reference))ordersAutoSyncRetryAt.delete(reference);
  const now=Date.now(),due=pending.filter(order=>(ordersAutoSyncRetryAt.get(order.paymentReference)||0)<=now&&!ordersSyncInFlight.has(order.paymentReference));
  if(!due.length)return;
  const count=Math.min(10,due.length),start=ordersAutoSyncCursor%due.length;
  const batch=Array.from({length:count},(_,index)=>due[(start+index)%due.length]);
  ordersAutoSyncCursor=(start+count)%due.length;
  let refreshed=false,checked=0,lastError='';
  for(const order of batch){
   if(document.hidden||activeOrdersList!==list||!list.isConnected)break;
   const reference=order.paymentReference;
   try{
    const result=await syncSandboxPayment(reference,session);checked++;
    if(result.payment_status==='pending')ordersAutoSyncRetryAt.set(reference,Date.now()+30000);
    else{ordersAutoSyncRetryAt.delete(reference);refreshed=true}
   }catch(error){ordersAutoSyncRetryAt.set(reference,Date.now()+60000);lastError=error.message||'Erro ao consultar o Mercado Pago.'}
  }
  if(refreshed&&activeOrdersList===list&&list.isConnected){
   await loadAdminOrders(session.access_token);
   if(activeOrdersList===list&&list.isConnected){renderOrdersList(list,feedback);feedback.textContent='Status dos pedidos atualizado automaticamente pelo Mercado Pago.'}
  }else if(lastError&&feedback&&activeOrdersList===list){
   feedback.textContent=`A consulta automática falhou; tentaremos novamente em até 60 segundos. ${lastError}`;
  }else if(checked&&feedback&&activeOrdersList===list&&feedback.textContent==='Acompanhamento automático ativo.'){
   feedback.textContent='Mercado Pago consultado. O pedido ainda está pendente; a próxima verificação será automática.';
  }
 }catch(error){if(feedback&&activeOrdersList===list)feedback.textContent=error.message||'A sincronização automática foi interrompida.'}
 finally{ordersAutoSyncBusy=false}
}
function startOrdersAutoSync(list,feedback){
 stopOrdersAutoSync();activeOrdersList=list;activeOrdersFeedback=feedback;
 ordersAutoSyncTimer=setInterval(()=>autoSyncSandboxOrders(list,feedback),30000);
 feedback.textContent='Acompanhamento automático ativo.';
 void autoSyncSandboxOrders(list,feedback);
}
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&activeOrdersList&&activeOrdersFeedback)void autoSyncSandboxOrders(activeOrdersList,activeOrdersFeedback)});
function renderOrdersList(list,feedback){
 list.innerHTML=orderTable(orders,{allowSync:true});
 list.querySelectorAll('[data-sync-sandbox]').forEach(button=>button.addEventListener('click',async()=>{
  const reference=button.dataset.syncSandbox;
  button.disabled=true;button.textContent='Consultando Mercado Pago…';feedback.textContent='';
  try{
   const session=await getAuthSession();if(!session)throw new Error('Sessão expirada. Entre novamente no painel.');
   const payload=await syncSandboxPayment(reference,session);
   if(payload.payment_status==='pending')ordersAutoSyncRetryAt.set(reference,Date.now()+30000);else ordersAutoSyncRetryAt.delete(reference);
   await loadAdminOrders(session.access_token);renderOrdersList(list,feedback);
   feedback.textContent=payload.payment_status==='pending'?'O Mercado Pago ainda informa pagamento pendente. A próxima verificação será automática.':`Pagamento sincronizado com o Mercado Pago: ${payload.payment_status||'status atualizado'}.`;
  }catch(error){feedback.textContent=error.message||'Não foi possível sincronizar o pedido.';button.disabled=false;button.textContent='Atualizar pagamento no MP'}
 }));
}
async function ordersView(){
 stopOrdersAutoSync();
 content.innerHTML=`<section class="admin-card"><div class="mobile-data-card-head"><div><h2>Pedidos</h2><p>Veja os produtos, variantes, quantidades, valores e endereço de cada compra. Para atualizar a etapa de expedição e o rastreio, use a aba <strong>Expedição</strong>. Pedidos sandbox pendentes são consultados automaticamente enquanto esta aba estiver aberta.</p></div><button class="button button-outline" id="refresh-orders" type="button">Atualizar</button></div><p id="orders-sync-feedback" class="sync-status" role="status" aria-live="polite"></p><div id="orders-list">Carregando pedidos…</div></section>`;
 const list=document.querySelector('#orders-list'),feedback=document.querySelector('#orders-sync-feedback');
 try{const session=await getAuthSession();if(!session)throw new Error('Sessão expirada. Entre novamente.');await loadAdminOrders(session.access_token);renderOrdersList(list,feedback);startOrdersAutoSync(list,feedback)}
 catch(error){backendOrdersError=error.message||'Não foi possível carregar os pedidos.';list.textContent=error.message||'Não foi possível carregar os pedidos.'}
 document.querySelector('#refresh-orders')?.addEventListener('click',()=>ordersView())
}
function renderShippingManager(){
 const list=document.querySelector('#shipping-orders-list');if(!list)return;
 const paid=orders.filter(order=>order.paymentStatus==='approved'&&order.shippingStatus!=='cancelled');
 const ready=paid.filter(order=>!['shipped','delivered'].includes(order.shippingStatus)),shipped=paid.filter(order=>order.shippingStatus==='shipped'),delivered=paid.filter(order=>order.shippingStatus==='delivered');
 for(const [key,value] of [['ready',ready.length],['shipped',shipped.length],['delivered',delivered.length],['all',paid.length]]){const summary=document.querySelector(`#shipping-count-${key}`),buttonCount=document.querySelector(`[data-shipping-count="${key}"]`);if(summary)summary.textContent=String(value);if(buttonCount)buttonCount.textContent=String(value)}
 const filtered=fulfillmentFilter==='ready'?ready:fulfillmentFilter==='shipped'?shipped:fulfillmentFilter==='delivered'?delivered:paid;
 document.querySelectorAll('[data-shipping-filter]').forEach(button=>{const active=button.dataset.shippingFilter===fulfillmentFilter;button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active))});
 list.innerHTML=orderTable(filtered,{allowManage:true,expandedProducts:true});
 list.querySelectorAll('[data-manage-fulfillment]').forEach(button=>button.addEventListener('click',()=>fulfillmentDialog(button.dataset.manageFulfillment,button.dataset.environment)));
}
async function shippingView(){
 stopOrdersAutoSync();
 content.innerHTML=`<section class="admin-card fulfillment-manager"><div class="mobile-data-card-head"><div><p class="eyebrow">OPERAÇÃO DA LOJA</p><h2>Expedição e rastreio</h2><p>Gerencie pedidos pagos, marque a etapa de envio e registre o código de rastreio. Pedidos sem pagamento confirmado ficam fora da fila de expedição.</p></div><button class="button button-outline" id="refresh-shipping" type="button">Atualizar</button></div><div class="fulfillment-summary"><article><span>Aguardando envio</span><strong id="shipping-count-ready">—</strong></article><article><span>Enviados</span><strong id="shipping-count-shipped">—</strong></article><article><span>Entregues</span><strong id="shipping-count-delivered">—</strong></article></div><div class="fulfillment-filter-list" role="group" aria-label="Filtrar pedidos por expedição"><button type="button" data-shipping-filter="ready" aria-pressed="true">Aguardando envio <b data-shipping-count="ready">0</b></button><button type="button" data-shipping-filter="shipped" aria-pressed="false">Enviados <b data-shipping-count="shipped">0</b></button><button type="button" data-shipping-filter="delivered" aria-pressed="false">Entregues <b data-shipping-count="delivered">0</b></button><button type="button" data-shipping-filter="all" aria-pressed="false">Todos pagos <b data-shipping-count="all">0</b></button></div><p id="fulfillment-feedback" class="sync-status" role="status" aria-live="polite"></p><div id="shipping-orders-list">Carregando pedidos…</div></section>`;
 try{const session=await getAuthSession();if(!session)throw new Error('Sessão expirada. Entre novamente.');await loadAdminOrders(session.access_token);renderShippingManager()}
 catch(error){document.querySelector('#shipping-orders-list').textContent=error.message||'Não foi possível carregar os pedidos.'}
 document.querySelectorAll('[data-shipping-filter]').forEach(button=>button.addEventListener('click',()=>{fulfillmentFilter=button.dataset.shippingFilter;renderShippingManager()}));
 document.querySelector('#refresh-shipping')?.addEventListener('click',()=>shippingView())
}
function fulfillmentDialog(orderId,environment){
 const order=orders.find(item=>item.dbId===orderId&&item.environment===environment);if(!order)return;
 const dialog=document.querySelector('#fulfillment-dialog');
 const statuses=[['pending','Aguardando envio'],['quoted','Frete definido'],['label_created','Etiqueta criada'],['shipped','Enviado'],['delivered','Entregue']];
 dialog.innerHTML=`<button class="close-button" id="fulfillment-close" type="button" aria-label="Fechar expedição">×</button><p class="eyebrow">${escapeHTML(order.id)} · ${escapeHTML(order.customer)}</p><h2 id="fulfillment-dialog-title">Atualizar expedição</h2><p>Pedido confirmado: ${money(order.total)}. Informe a etapa atual e, se já tiver, o código de rastreio.</p><form id="fulfillment-form" class="admin-form"><label class="span-all">Status do envio<select name="shipping_status" required>${statuses.map(([value,label])=>`<option value="${value}" ${order.shippingStatus===value?'selected':''}>${label}</option>`).join('')}</select></label><label class="span-all">Código de rastreio<input name="tracking_code" maxlength="120" value="${escapeHTML(order.trackingCode)}" placeholder="Ex.: BR123456789XX"></label><p class="span-all form-help">A compra da etiqueta não acontece aqui. Registre o status e o código fornecidos pela transportadora.</p><p class="span-all sync-status" data-form-status role="status" aria-live="polite"></p><div class="span-all modal-actions"><button class="button button-dark" type="submit">Salvar expedição</button><button class="button button-outline" id="fulfillment-cancel" type="button">Cancelar</button></div></form>`;
 dialog.querySelector('#fulfillment-close').onclick=()=>dialog.close();dialog.querySelector('#fulfillment-cancel').onclick=()=>dialog.close();
 const form=dialog.querySelector('#fulfillment-form'),submit=form.querySelector('[type="submit"]'),status=form.querySelector('[data-form-status]');
 form.addEventListener('submit',async event=>{event.preventDefault();submit.disabled=true;submit.textContent='Salvando…';status.classList.remove('sync-error');status.textContent='Gravando status no Supabase…';try{const session=await getAuthSession();if(!session)throw new Error('Sessão expirada. Entre novamente no painel.');await adminRest('rpc/admin_update_store_order_fulfillment',{method:'POST',body:{p_order_id:order.dbId,p_environment:order.environment,p_shipping_status:form.elements.shipping_status.value,p_tracking_code:form.elements.tracking_code.value.trim()||null},token:session.access_token});await loadAdminOrders(session.access_token);dialog.close();if(activeAdminView==='shipping')renderShippingManager();else if(activeAdminView==='orders'){const list=document.querySelector('#orders-list'),feedback=document.querySelector('#orders-sync-feedback');if(list&&feedback)renderOrdersList(list,feedback)}else if(activeAdminView==='overview')overview();const feedback=document.querySelector('#fulfillment-feedback');if(feedback)feedback.textContent='Etapa de expedição salva.'}catch(error){status.textContent=error.message||'Não foi possível salvar a etapa de envio.';status.classList.add('sync-error')}finally{submit.disabled=false;submit.textContent='Salvar expedição'}});
 dialog.showModal();
}
function inventoryView(){const sorted=products.slice().sort((a,b)=>a.stock-b.stock);const rows=sorted.map(p=>`<tr><td>${escapeHTML(p.name)}</td><td>${escapeHTML(p.sku)}</td><td>${p.stock}</td><td><span class="status-label ${p.stock<6?'pending':''}">${p.stock<6?'Revisar demonstração':'Exemplo'}</span></td><td><button class="text-link" data-stock-edit="${escapeHTML(p.id)}">Editar</button></td></tr>`).join('');const cards=sorted.map(p=>`<article class="mobile-data-card"><div class="mobile-data-card-head"><h3>${escapeHTML(p.name)}</h3><span class="status-label ${p.stock<6?'pending':''}">${p.stock<6?'Revisar demonstração':'Exemplo'}</span></div><dl><div><dt>SKU</dt><dd>${escapeHTML(p.sku)}</dd></div><div><dt>Estoque</dt><dd>${p.stock} unidades</dd></div></dl><button class="button button-outline" type="button" data-stock-edit="${escapeHTML(p.id)}">Editar produto e estoque</button></article>`).join('');content.innerHTML=`<section class="admin-card inventory-panel"><h2>Níveis de estoque</h2><p>O ajuste de estoque é gravado nas variantes do produto no Supabase.</p><div class="desktop-data-view table-wrap"><table class="admin-table admin-table-inventory"><thead><tr><th>Produto</th><th>SKU</th><th>Estoque</th><th>Faixa</th><th></th></tr></thead><tbody>${rows}</tbody></table></div><div class="mobile-data-view" aria-label="Estoque">${cards}</div></section>`;content.querySelectorAll('[data-stock-edit]').forEach(button=>button.onclick=()=>productDialog(products.find(p=>p.id===button.dataset.stockEdit)))}
function settingsView(){content.innerHTML=`<div class="config-grid"><section class="admin-card"><p class="eyebrow">LOJA</p><h2>Fio de Varanda</h2><p>Projeto conceitual para portfólio.</p><strong>WhatsApp</strong><p>(83) 99873-9712</p></section><section class="admin-card"><p class="eyebrow">DOMÍNIO CANDIDATO</p><h2>fio-de-varanda.com.br</h2><p>É necessário registrar o domínio e configurar DNS no provedor antes de usá-lo.</p></section><section class="admin-card"><p class="eyebrow">INTEGRAÇÕES</p><h2>Mercado Pago e Melhor Envio</h2><p>Checkout de produção protegido por Edge Functions. Configure credenciais, URL HTTPS, CEP de origem e medidas reais do catálogo no Supabase.</p><button class="button button-outline" id="connect-me-button" type="button">Conectar Melhor Envio</button><p id="integration-status" class="sync-status" role="status" aria-live="polite"></p></section><section class="admin-card"><p class="eyebrow">DADOS</p><h2>Catálogo no Supabase</h2><p>Produtos e estoque são mantidos no backend. Pedidos reais são registrados pelo checkout server-side e só mudam para pago após webhook Mercado Pago validado. A compra da etiqueta não é automática nesta etapa.</p></section></div>`;document.querySelector('#connect-me-button')?.addEventListener('click',connectMelhorEnvio)}
async function connectMelhorEnvio(){const button=document.querySelector('#connect-me-button'),status=document.querySelector('#integration-status');if(!button||!status)return;button.disabled=true;button.textContent='Abrindo autorização…';status.textContent='Validando sessão administrativa…';try{const session=await getAuthSession();if(!session)throw new Error('Entre novamente no painel.');const response=await fetch(`${supabaseConfig.supabaseUrl}/functions/v1/melhor-envio-oauth-start`,{method:'POST',headers:{apikey:supabaseConfig.supabasePublishableKey,Authorization:`Bearer ${session.access_token}`,'Content-Type':'application/json'},body:'{}'});const result=await response.json();if(!response.ok||!result.authorization_url)throw new Error('Configure client ID, client secret e callback do Melhor Envio nos segredos do Supabase antes de conectar.');location.assign(result.authorization_url)}catch(error){status.textContent=error.message||'Não foi possível iniciar a conexão.';button.disabled=false;button.textContent='Conectar Melhor Envio'}}
